    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                stack=[(r,c)]; cells=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen or g[y][x]!=bg: continue
                    seen.add((y,x)); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
