                                stack.append((ny,nx))
                rows=min(y for y,x in cells); cols=max(x for y,x in cells)
                shape=[(y-rows,x-cols) for y,x in cells]
                out.append((cells,shape,(min(x for y,x in cells),max(y for y,x in cells))))
    return out
